--- ReplicatedStorage.CmdrClient.Types.pollArguments [ModuleScript]
-- y u r i

local function validateChoices(arg1, arg2)
	local var1 = string.split(arg1, ",")
	local tbl1 = {}
	if 4 < (#var1) then
		return false, "Use at most 4 choices."
	end

	for k1, v1 in var1, nil do
		v1 = v1:match("^%s*(.-)%s*$")
		if v1 == "" then
			if arg2 or k1 ~= (#var1) then
				return false, "Choices cannot be empty."
			end
		else
			if 40 < (#v1) or v1:find("[%c]") then
				return false, "Each choice must be 1-40 bytes."
			end

			if tbl1[v1:lower()] then
				return false, "Each choice must be different."
			end

			local var2 = v1:lower()
			tbl1[var2] = true
		end
	end

	if arg2 and #var1 < 2 then
		return false, "Add a comma and a second choice (2-4 total)."
	end

	return true
end

return function(arg1)
	arg1:RegisterType("pollQuestion", {
		Validate = function(arg1)
			local bool1 = false
			if 0 < (#arg1:match("^%s*(.-)%s*$")) then
				bool1 = #arg1 <= 160
			end

			return bool1, "Enter a question (up to 160 bytes). Put multiword questions in double quotes."
		end,
		Parse = function(arg1)
			return (arg1:match("^%s*(.-)%s*$"))
		end,
	})

	arg1:RegisterType("pollChoices", {
		Validate = function(arg1)
			local var1 = arg1
			local bool1 = false
			return validateChoices(var1, bool1)
		end,
		ValidateOnce = function(arg1)
			local var1 = arg1
			local bool1 = true
			return validateChoices(var1, bool1)
		end,
		Parse = function(arg1)
			return arg1
		end,
	})

	arg1:RegisterType("pollTime", {
		Validate = function(arg1)
			local var2 = tonumber(arg1)
			local bool2 = false
			if var2 ~= nil then
				bool2 = false
				if var2 == math.floor(var2) then
					bool2 = false
					if 1 <= var2 then
						bool2 = var2 <= 300
					end
				end
			end

			return bool2, "Use whole seconds from 1 to 300. Omit this argument for 15 seconds."
		end,
		Parse = tonumber,
	})
end

